CREATE TABLE "SchemaMetadata" ("singleton" INTEGER NOT NULL PRIMARY KEY CHECK ("singleton" = 1), "version" INTEGER NOT NULL, "applicationVersion" TEXT NOT NULL);
INSERT INTO "SchemaMetadata" VALUES (1, 1, '0.1.0');
CREATE TABLE "League" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL);
CREATE TABLE "Season" ("id" TEXT NOT NULL PRIMARY KEY, "leagueId" TEXT NOT NULL, "year" INTEGER NOT NULL, "name" TEXT NOT NULL, "state" TEXT NOT NULL, "teamCount" INTEGER NOT NULL CHECK ("teamCount" > 0), "rowVersion" INTEGER NOT NULL DEFAULT 0, "active" INTEGER NOT NULL DEFAULT 0, "createdAt" TEXT NOT NULL, "updatedAt" TEXT NOT NULL, FOREIGN KEY ("leagueId") REFERENCES "League"("id"), UNIQUE("leagueId", "year"));
CREATE TABLE "Team" ("id" TEXT NOT NULL PRIMARY KEY, "leagueId" TEXT NOT NULL, "franchiseName" TEXT NOT NULL, FOREIGN KEY ("leagueId") REFERENCES "League"("id"));
CREATE TABLE "SeasonTeam" ("id" TEXT NOT NULL PRIMARY KEY, "seasonId" TEXT NOT NULL, "teamId" TEXT NOT NULL, "displayName" TEXT NOT NULL, "seedOrder" INTEGER NOT NULL, "active" INTEGER NOT NULL DEFAULT 1, FOREIGN KEY ("seasonId") REFERENCES "Season"("id"), FOREIGN KEY ("teamId") REFERENCES "Team"("id"), UNIQUE("seasonId", "teamId"), UNIQUE("seasonId", "seedOrder"));
CREATE TABLE "AuditEvent" ("id" TEXT NOT NULL PRIMARY KEY, "seasonId" TEXT NOT NULL, "sequence" INTEGER NOT NULL, "actorType" TEXT NOT NULL, "actorLabel" TEXT NOT NULL, "commandType" TEXT NOT NULL, "entityType" TEXT, "entityId" TEXT, "correlationId" TEXT NOT NULL, "idempotencyKey" TEXT NOT NULL, "reason" TEXT, "beforeJson" TEXT, "afterJson" TEXT, "resultJson" TEXT, "createdAt" TEXT NOT NULL, FOREIGN KEY ("seasonId") REFERENCES "Season"("id"), UNIQUE("seasonId", "sequence"), UNIQUE("seasonId", "actorType", "idempotencyKey"));
CREATE TABLE "FrozenSnapshot" ("id" TEXT NOT NULL PRIMARY KEY, "seasonId" TEXT NOT NULL, "kind" TEXT NOT NULL, "schemaVersion" INTEGER NOT NULL, "payloadJson" TEXT NOT NULL, "sha256" TEXT NOT NULL, "createdAt" TEXT NOT NULL, "sourceAuditEventId" TEXT NOT NULL, FOREIGN KEY ("seasonId") REFERENCES "Season"("id"), FOREIGN KEY ("sourceAuditEventId") REFERENCES "AuditEvent"("id"));
CREATE TABLE "Checkpoint" ("id" TEXT NOT NULL PRIMARY KEY, "seasonId" TEXT NOT NULL, "kind" TEXT NOT NULL, "seasonVersion" INTEGER NOT NULL, "stateSnapshotId" TEXT NOT NULL, "sourceAuditEventId" TEXT NOT NULL, "createdAt" TEXT NOT NULL, "supersededAt" TEXT, FOREIGN KEY ("seasonId") REFERENCES "Season"("id"), FOREIGN KEY ("stateSnapshotId") REFERENCES "FrozenSnapshot"("id"), FOREIGN KEY ("sourceAuditEventId") REFERENCES "AuditEvent"("id"));
CREATE TRIGGER "AuditEvent_append_only_update" BEFORE UPDATE ON "AuditEvent" BEGIN SELECT RAISE(ABORT, 'AuditEvent is append-only'); END;
CREATE TRIGGER "AuditEvent_append_only_delete" BEFORE DELETE ON "AuditEvent" BEGIN SELECT RAISE(ABORT, 'AuditEvent is append-only'); END;
